#!/usr/bin/env python3
"""You already have a physical board (not one generated by this repo) and
may not know which ArUco dictionary it was made with -- guessing wrong
means cv2.aruco silently detects nothing, with no clue why. This tries
every commonly-used predefined dictionary against a photo of the board and
reports which one(s) actually find markers.

Usage: identify_board_dictionary.py <image_path>
  (grab one with: ros2 topic echo --once /landfill/rgb/image_raw ...
   or more simply, point the board at the camera and use
   board/grab_one_frame.py <topic> <output.png>)
"""
import sys

import cv2

CANDIDATE_DICTS = [
    'DICT_4X4_50', 'DICT_4X4_100', 'DICT_4X4_250', 'DICT_4X4_1000',
    'DICT_5X5_50', 'DICT_5X5_100', 'DICT_5X5_250', 'DICT_5X5_1000',
    'DICT_6X6_50', 'DICT_6X6_100', 'DICT_6X6_250', 'DICT_6X6_1000',
    'DICT_7X7_50', 'DICT_7X7_100', 'DICT_7X7_250', 'DICT_7X7_1000',
    'DICT_ARUCO_ORIGINAL',
    'DICT_APRILTAG_16h5', 'DICT_APRILTAG_25h9', 'DICT_APRILTAG_36h10', 'DICT_APRILTAG_36h11',
]


def main():
    img_path = sys.argv[1]
    img = cv2.imread(img_path, cv2.IMREAD_GRAYSCALE)
    if img is None:
        print(f'could not read {img_path}')
        sys.exit(1)

    params = cv2.aruco.DetectorParameters_create() if hasattr(cv2.aruco, 'DetectorParameters_create') \
        else cv2.aruco.DetectorParameters()

    results = []
    for name in CANDIDATE_DICTS:
        if not hasattr(cv2.aruco, name):
            continue
        dictionary = cv2.aruco.getPredefinedDictionary(getattr(cv2.aruco, name))
        if hasattr(cv2.aruco, 'ArucoDetector'):
            detector = cv2.aruco.ArucoDetector(dictionary, params)
            corners, ids, _rejected = detector.detectMarkers(img)
        else:
            corners, ids, _rejected = cv2.aruco.detectMarkers(img, dictionary, parameters=params)
        n = 0 if ids is None else len(ids)
        if n > 0:
            results.append((name, n, sorted(int(i) for i in ids.flatten())))

    if not results:
        print('No markers found with ANY predefined dictionary. Likely causes: the image is '
              'too blurry/dark/small, the board isn\'t a standard predefined-dictionary ArUco '
              'set (some generators make custom dictionaries), or the image path/crop is wrong. '
              'Try a clearer, well-lit, closer photo first.')
        sys.exit(1)

    results.sort(key=lambda r: -r[1])
    print(f'{len(results)} dictionar(y/ies) found markers in this image:\n')
    for name, n, ids in results:
        print(f'  {name}: {n} markers, ids={ids}')
    print(f'\nMost likely match: {results[0][0]} ({results[0][1]} markers detected)')
    print(f'Set this as `dictionary:` in config/board_config.yaml.')
    if len(results) > 1:
        print('Multiple dictionaries matched (common -- small dictionaries are often subsets '
              'of larger ones of the same bit-size) -- the one with the most matches and the '
              'smallest total dictionary size that still covers your marker ids is usually '
              'correct.')


if __name__ == '__main__':
    main()
